style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
body {
    background-image: url("https://i.postimg.cc/Dz1RzdZK/hmhas.png");
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    background-repeat: no-repeat;
  }

  /* Make white blocks see-through */
  .container-main, .content, .gamepage-container, .navbar, .footer-container,
  .home-container, .text, .section, .container, .games-list,
  .rbx-header, .game-card-container {
    background: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(6px);
  }
}
